#ifndef _IN_RTP_H_
#define _IN_RTP_H_

/*module interface*/
#include <gpac/filters.h>
#include <gpac/constants.h>
#ifndef GPAC_DISABLE_STREAMING

#include <gpac/base_coding.h>
#include <gpac/mpeg4_odf.h>
/*IETF lib*/
#include <gpac/internal/ietf_dev.h>

#include <gpac/download.h>

#define RTSP_BUFFER_SIZE                5000

typedef struct _rtsp_session GF_RTPInRTSP;
typedef struct __rtpin_stream GF_RTPInStream;

enum
{
        RTP_TRANSPORT_AUTO=0,
        RTP_TRANSPORT_TCP_ONLY,
        RTP_TRANSPORT_UDP_ONLY,
};

enum
{
        RETRY_RTSP_NONE=0,
        RETRY_RTSP_NORMAL,
        RETRY_RTSP_FORCE_TCP,
        RETRY_RTSP_PENDING = 1<<8,
};

/*the rtsp/rtp client*/
typedef struct
{
        //opts
        char *src;
        u32 firstport, ttl, satip_port;
        const char *ifce, *force_mcast, *user_agent, *languages;
        Bool use_client_ports;
        u32 bandwidth, reorder_len, reorder_delay, nat_keepalive, block_size;
        Bool disable_rtcp;
        u32 default_port;
        u32 udp_timeout, rtcp_timeout, stats;
        Bool forceagg;
        /*transport mode. 0 is udp, 1 is tcp, 3 is tcp if unreliable media */
        u32 transport;
        s32 max_sleep, loss_rate;
        Bool rtcpsync;
        GF_PropStringList ssm, ssmx;

        //internal

        GF_Filter *filter;

        /*the service we're responsible for*/
        GF_FilterPid *ipid;
        u32 sdp_url_crc;
        Bool sdp_loaded;

        /*one and only RTSP session*/
        GF_RTPInRTSP *session;

        /*RTP/RTCP media streams*/
        GF_List *streams;

        /*RTSP config*/

        /*packet drop emulation*/
        u32 first_packet_drop;
        u32 frequency_drop;

        /*for single-object control*/
        u32 stream_type;

        GF_Descriptor *iod_desc;

        GF_RTPInStream *postponed_play_stream;
        GF_FEVT_Play postponed_play;

        /*if set ANNOUNCE (sent by server) will be handled*/
//      Bool handle_announce;

        Double last_ntp;

        Bool is_scalable, done;
        u32 retry_rtsp;

        Double last_start_range;

        u32 cur_mid;

                /*channel not found, send describe on service*/
        }

        /*send describe*/
        com = gf_rtsp_command_new();
        if (!sess->satip) {
                com->method = gf_strdup(GF_RTSP_DESCRIBE);
        } else {
                GF_Err e;
                GF_RTSPTransport *trans;
                GF_RTPInStream *stream = NULL;

                com->method = gf_strdup(GF_RTSP_SETUP);

                /*setup transport ports*/
                GF_SAFEALLOC(trans, GF_RTSPTransport);
                if (trans) {
                        trans->IsUnicast = GF_TRUE;
                        trans->client_port_first = sess->rtpin->satip_port;
                        trans->client_port_last = sess->rtpin->satip_port+1;
                        trans->Profile = gf_strdup(GF_RTSP_PROFILE_RTP_AVP);
                        gf_list_add(com->Transports, trans);
                }

                /*hardcoded channel*/
                stream = rtpin_stream_new_standalone(sess->rtpin, sess->satip_server, 0, GF_TRUE);
                if (!stream) {
                        GF_LOG(GF_LOG_ERROR, GF_LOG_RTP, ("SAT>IP: couldn't create the RTP stream.\n"));
                        return;
                }
                e = rtpin_add_stream(sess->rtpin, stream, "*");
                if (e) {
                        GF_LOG(GF_LOG_ERROR, GF_LOG_RTP, ("SAT>IP: couldn't add the RTP stream.\n"));
                        return;
                }
                com->user_data = stream;
        }

        if (opid || esd_url) {
                com->Accept = gf_strdup("application/sdp");
                com->ControlString = esd_url ? gf_strdup(esd_url) : NULL;

                ch_desc = (RTPIn_StreamDescribe *)gf_malloc(sizeof(RTPIn_StreamDescribe));
                ch_desc->esd_url = esd_url ? gf_strdup(esd_url) : NULL;
                ch_desc->opid = opid;

                com->user_data = ch_desc;
        } else {
                //always accept both SDP and IOD
                com->Accept = gf_strdup("application/sdp, application/mpeg4-iod");
//              com->Accept = gf_strdup("application/sdp");
        }

        /*need better tuning ...*/
        if (sess->rtpin->bandwidth)
                com->Bandwidth = sess->rtpin->bandwidth;

        rtpin_rtsp_queue_command(sess, NULL, com, GF_FALSE);
}


